div.script:
async function Load() {
    const response = await fetch("https://instel12.github.io/ThatOneSiteWithGames/Singlefile.html");
    const text = await response.text();
    const tab = window.open("about:blank", "_blank");
    tab.document.open();
    tab.document.write(text);
    tab.document.close();
}
